import { Icon } from '@cetus/ui-kit'
import {
  Box,
  Button,
  Divider,
  HStack,
  Image,
  Input,
  InputGroup,
  InputLeftAddon,
  Popover,
  PopoverBody,
  PopoverContent,
  PopoverFooter,
  PopoverHeader,
  PopoverTrigger,
  Portal,
  SelectField,
  Text,
  VStack
} from '@chakra-ui/react'
import NavLink from '../common/NavLink'
import { NotificationsProps } from './type'

interface IFormItemProps {
  children: React.ReactNode
  label: string
}

const FormItem = ({ label, children }: IFormItemProps) => {
  return (
    <InputGroup h="52px" borderRadius="12px" p="16px" bg="#141414" border="1px solid" borderColor="border">
      <InputLeftAddon fontSize="14px" h="20px" lineHeight="20px" w="106px">
        {label}
      </InputLeftAddon>
      <Box borderColor="border" pr="16px">
        <Divider orientation="vertical" />
      </Box>

      {children}
    </InputGroup>
  )
}

function Notifications({ params, onParamsChange, onSubscribe }: NotificationsProps) {
  return (
    <Popover>
      <PopoverTrigger>
        <Box
          w="36px"
          h="36px"
          p="7px"
          bg="bg_secondary"
          borderRadius="8px"
          border="1px solid"
          borderColor="border"
          cursor="pointer"
          _hover={{ bg: 'menu_item_hover_bg' }}
        >
          <Icon xlinkHref="#icon-icon_notification" variant="gray" />
        </Box>
      </PopoverTrigger>
      <Portal>
        <PopoverContent p="16px" bg="bg_secondary" border="1px solid" borderColor="border" minW="420px">
          <PopoverHeader border="none" fontSize="16px" fontWeight="500" p="0px 0px 16px">
            Notifications Setting
          </PopoverHeader>
          <PopoverBody>
            <VStack gap="16px">
              <FormItem label="Email address">
                <Input
                  type="email"
                  placeholder="Email address"
                  fontSize="14px"
                  h="20px"
                  lineHeight="20px"
                  value={params.email}
                  onChange={e => onParamsChange(e, 'email')}
                />
              </FormItem>
              <FormItem label="Phone number">
                <SelectField fontSize="14px" color="text_caption" onChange={e => onParamsChange(e, 'phone')}>
                  <option value="1">1</option>
                  <option value="86">86</option>
                </SelectField>
                <Input type="tel" placeholder="Phone number" pl="16px" fontSize="14px" h="20px" lineHeight="20px" value={params.phone} />
              </FormItem>
              <FormItem label="Telegram ID">
                <Input
                  type="number"
                  placeholder="Telegram ID"
                  fontSize="14px"
                  h="20px"
                  lineHeight="20px"
                  value={params.id}
                  onChange={e => onParamsChange(e, 'id')}
                />
              </FormItem>
              <Button w="100%" h="40px" borderRadius="12px" fontWeight="500" fontSize="16px" onClick={onSubscribe}>
                Subscribe
              </Button>
            </VStack>
          </PopoverBody>
          <PopoverFooter border="none">
            <Text fontSize="12px" color="text_paragraph" lineHeight="20px">
              Notifications are provided by Notifi. By subscribing, you agree that info you provide to Notifi will be governed by its{' '}
              <NavLink link="/" fontSize="12px" textDecoration="underline">
                Privacy Policy
              </NavLink>{' '}
              and{' '}
              <NavLink link="/" fontSize="12px" textDecoration="underline">
                Terms of Use .
              </NavLink>
            </Text>
            <HStack justify="center">
              <Text fontSize="14px" color="text_paragraph">
                Powered by
              </Text>
              <Image src="/images/notifi@2x.png" h="20px" />
            </HStack>
          </PopoverFooter>
        </PopoverContent>
      </Portal>
    </Popover>
  )
}

export default Notifications
