import RPCContent from '../RPCContent'
import { RPCNodeInterface } from '../type'
import PCSettingItem from './Item'

interface RPCProps extends RPCNodeInterface {
  showMainSetting: boolean
  closeModal: () => void
}

const PCRPCNode = ({ showMainSetting, closeModal }: RPCProps) => {
  return (
    showMainSetting && (
      <PCSettingItem icon="#icon-icon_rpc" label="RPC Node">
        <RPCContent closeModal={closeModal} />
      </PCSettingItem>
    )
  )
}

export default PCRPCNode
