import { Icon } from '@cetus/ui-kit'
import {
  Box,
  HStack,
  Popover,
  PopoverBody,
  PopoverCloseButton,
  PopoverContent,
  PopoverHeader,
  PopoverTrigger,
  Text,
  useDisclosure,
  VStack
} from '@chakra-ui/react'
import { useMemo, useState } from 'react'
import { SettingProps } from '../type'
import PCLanguage from './Language'
import PCPreferred from './Preferred'
import PCRPCNode from './RPCNode'
interface PCSettings extends SettingProps {
  isCetusPump: boolean
}
const PCSettings = ({ language, preferred, rpcNode, isCetusPump }: PCSettings) => {
  const { isOpen, onOpen, onClose } = useDisclosure()
  const [title, setTitle] = useState('Settings')
  const showMainSetting = useMemo(() => title === 'Settings', [title])
  const handleTitleChange = (value: string) => {
    setTitle(value)
  }

  const onBackMainSetting = () => {
    setTitle('Settings')
  }
  return (
    <Popover isOpen={isOpen} onOpen={onOpen} placement="bottom-end" onClose={onClose}>
      <PopoverTrigger>
        <Box
          bg="bg_secondary"
          w="36px"
          h="36px"
          p="7px"
          border="1px solid"
          borderColor="border"
          borderRadius="8px"
          _hover={{ bg: 'menu_item_hover_bg' }}
        >
          <Icon xlinkHref="#icon-icon_settings" variant="gray" />
        </Box>
      </PopoverTrigger>
      <PopoverContent minW="360px" p="0px 16px 16px" bg="bg_secondary" borderRadius="12px" border="1px solid" borderColor="border">
        <PopoverHeader p="0px" fontWeight="500" h="56px" lineHeight="56px" border="none">
          <HStack>
            {!showMainSetting && (
              <Icon xlinkHref="#icon-icon_descending" transform="rotate(90deg)" svgFill="text_caption" fontSize="16px" onClick={onBackMainSetting} />
            )}
            <Text color="text_caption" fontSize="16px">
              {title}
            </Text>
          </HStack>
        </PopoverHeader>
        {!showMainSetting && <PopoverCloseButton h="50px" onClick={onBackMainSetting} />}

        <PopoverBody p="0px">
          <VStack>
            {!isCetusPump && (
              <PCLanguage
                value={language.value}
                options={language.options}
                onValueChange={value => language.onValueChange(value)}
                onShowOptions={() => handleTitleChange('Language')}
                showOptions={title === 'Language'}
                showMainSetting={showMainSetting}
              />
            )}
            <PCPreferred
              value={preferred.value}
              options={preferred.options}
              onValueChange={value => preferred.onValueChange(value)}
              onShowOptions={() => handleTitleChange('Preferred')}
              showOptions={title === 'Preferred'}
              showMainSetting={showMainSetting}
              closeModal={onBackMainSetting}
            />
            <PCRPCNode {...rpcNode} showMainSetting={showMainSetting} closeModal={onClose} />
          </VStack>
        </PopoverBody>
      </PopoverContent>
    </Popover>
  )
}

export default PCSettings
