import NavLink from '@/components/common/NavLink'
import NavMenu from '@/components/nav/NavMenu'
import Notifications from '@/components/nav/Notifications'
import ConnectButton from '@/components/wallet/ConnectButton'
import { isMenuActive } from '@/utils'
import { useJump2Dex } from '@cetus/hooks/src/useJump2Dex'
import { BackButton, SwitchChain } from '@cetus/ui-kit'
import { Flex, Image, Text } from '@chakra-ui/react'
import { useLocation } from 'react-router-dom'
import PCSettings from '../settings/pc'
import { IMenusProps, MenuItemWithChildren, MenuItemWithoutChildren } from '../type'

const PCHeader = ({ menus, logo, setting, notifications, chain, jump, isCetusPump }: IMenusProps) => {
  const { pathname } = useLocation()
  const { back2Dex } = useJump2Dex()
  return (
    <Flex w="100%" justifyContent="space-between" align="center" h="80px" p="0px 20px">
      <Flex align="center" gap={{ lg: '16px', xl: '48px' }}>
        <Image src={logo.image} h="32px" alt="logo" onClick={() => jump(logo.url)} />
        <Flex align="center" gap={{ lg: '12px', xl: '32px' }}>
          {menus?.map(menu => {
            if ((menu as any)?.children) {
              return (
                <NavMenu
                  key={menu.title}
                  title={menu.title}
                  isActive={isMenuActive(menu as any, pathname)}
                  list={(menu as MenuItemWithChildren).children}
                  socials={(menu as MenuItemWithChildren).socials}
                />
              )
            } else {
              return (
                <NavLink
                  key={menu.title}
                  link={(menu as MenuItemWithoutChildren).path}
                  isActive={isMenuActive(menu as MenuItemWithoutChildren, pathname)}
                >
                  <Text color="inherit" fontSize="15px" fontWeight="500">
                    {menu.title}
                  </Text>
                </NavLink>
              )
            }
          })}
        </Flex>
      </Flex>
      <Flex align="center" gap={{ lg: '4px', xl: '8px' }}>
        {isCetusPump && <BackButton w={{ lg: '98px', xl: '114px' }} h="36px" text="Back to DEX" onClick={() => jump('/')} />}
        {chain && <SwitchChain {...chain} />}
        <ConnectButton isCetusPump={isCetusPump} />
        {notifications && <Notifications {...notifications} />}

        <PCSettings {...setting} isCetusPump={isCetusPump} />
      </Flex>
    </Flex>
  )
}

export default PCHeader
