import { VStack } from '@chakra-ui/react'
import ListItem from '../ListItem'
import { IPCtemSettingInterface } from '../type'
import PCSettingItem from './Item'

const PCLanguage = ({ value, options, onValueChange, onShowOptions, showOptions, showMainSetting }: IPCtemSettingInterface) => {
  return showOptions ? (
    <VStack w="100%">
      {options.map(item => {
        return <ListItem key={item} label={item} value={item} isActive={item === value} onClick={() => onValueChange(item)} />
      })}
    </VStack>
  ) : (
    showMainSetting && <PCSettingItem icon="#icon-icon_language" label="Language" value={value} onClick={onShowOptions} />
  )
}

export default PCLanguage
