import { Icon } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Box, Button, Center, Divider, Flex, HStack, Menu, MenuButton, MenuItem, MenuList, Text } from '@chakra-ui/react'
import { MouseEvent, useState } from 'react'
import { Link as ReactRouterLink, useLocation, useNavigate } from 'react-router-dom'
import { NavMenuListItem, NavMenuProps } from './type'

export default function NavMenu(props: NavMenuProps) {
  const { title, list, isActive, socials, ...rest } = props
  const navigate = useNavigate()
  const { pathname } = useLocation()
  const [open, setOpen] = useState(false)
  const [isChildOpen, setIsChildOpen] = useState(false)
  const handleMouseEnter = (event?: MouseEvent<HTMLDivElement>) => {
    // 冒泡没起作用哦？
    event?.stopPropagation()
    setOpen(true)
  }
  const handleMouseLeave = (event?: MouseEvent<HTMLDivElement>) => {
    event?.stopPropagation()
    setOpen(false)
  }

  return (
    <Box
      mb="-8px"
      h={{
        md: open ? '140px' : 'auto',
        lg: 'auto'
      }}
    >
      <Box pb="8px" onClick={() => setOpen(!open)} onMouseLeave={handleMouseLeave} onMouseEnter={handleMouseEnter}>
        <Menu id="more" isOpen={open} onClose={() => handleMouseLeave()} placement="bottom-start" {...rest}>
          {({ isOpen }) => (
            <>
              <MenuButton
                p="0"
                isActive={isOpen}
                as={Button}
                bg="none"
                _hover={{ bg: 'none', p: { color: 'text_caption' }, svg: { fill: 'text_caption' } }}
                _active={{ bg: 'none' }}
              >
                <Center gap="4px">
                  <Text color={isActive ? 'text_caption' : 'text_paragraph'} position="relative" fontSize="15px" fontWeight="500">
                    {title}
                  </Text>
                  <Icon
                    svgH="12px"
                    svgW="12px"
                    boxH="12px"
                    boxW="12px"
                    xlinkHref="#icon-icon_arrow"
                    variant="gray"
                    svgFill="primary_gray"
                    transition="transform 0.5s"
                    transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
                  />
                </Center>
              </MenuButton>
              <MenuList
                p="8px"
                display="flex"
                flexDir="column"
                gap="8px"
                minW="unset"
                ml={{
                  md: '-16px',
                  lg: '0px'
                }}
                mt={{
                  md: '-20px',
                  lg: '0px'
                }}
                bg={{
                  md: 'bg_secondary',
                  lg: 'bg_secondary'
                }}
                backdropFilter={{
                  md: 'none',
                  lg: 'blur(80px)'
                }}
              >
                {list.map((item: NavMenuListItem) => {
                  const active = pathname.startsWith(item.path as string)
                  return item.children ? (
                    <MenuItemWithChildren key={item.title} item={item} active={active} isActive={isActive} />
                  ) : (
                    <Item key={item.title} item={item} active={active} />
                  )
                })}
                {socials && (
                  <HStack minW="220px">
                    {socials?.map(social => {
                      return (
                        <MenuItem
                          key={social.title}
                          flex="1"
                          as="a"
                          href={social.path}
                          target="_blank"
                          bg="menu_item_bg"
                          borderRadius="8px"
                          padding="14px"
                          minW="48px"
                          sx={{
                            h: '48px',
                            p: {
                              color: 'text_paragraph'
                            },
                            svg: {
                              fill: 'text_paragraph'
                            }
                          }}
                          _hover={{
                            p: {
                              color: 'text_caption'
                            },
                            svg: {
                              fill: 'text_caption'
                            }
                          }}
                        >
                          {social.icon ? (
                            <Box>
                              {typeof social.icon === 'string' ? (
                                <Icon xlinkHref={social.icon} />
                              ) : (
                                <Icon xlinkHref={social.icon.xlinkHref} variant={social.icon.variant || ''} />
                              )}
                            </Box>
                          ) : null}
                        </MenuItem>
                      )
                    })}
                  </HStack>
                )}
              </MenuList>
            </>
          )}
        </Menu>
      </Box>
    </Box>
  )
}

const MenuItemWithChildren = ({ item, active, isActive }: { item: NavMenuListItem; active: boolean; isActive?: boolean }) => {
  const [open, setOpen] = useState(false)

  return (
    <Box bg="menu_item_bg" borderRadius="8px" p="0 16px">
      <MenuItem
        as={Button}
        variant="unstyled"
        w="100%"
        h="52px"
        bg="menu_item_bg"
        borderRadius="8px"
        padding="16px 0px"
        sx={{
          p: {
            color: active ? 'text_caption' : 'text_paragraph'
          },
          svg: {
            fill: active ? 'text_caption' : 'text_paragraph'
          }
        }}
        _hover={{
          p: {
            color: 'text_caption'
          },
          svg: {
            fill: 'text_caption'
          }
        }}
        onClick={e => {
          cancelBubble(e)
          setOpen(!open)
        }}
        closeOnSelect={false}
      >
        <Flex align="center" w="100%" justify="space-between">
          <HStack gap="0px">
            {item.icon ? (
              <Box mr="12px">
                {typeof item.icon === 'string' ? (
                  <Icon xlinkHref={item.icon} />
                ) : (
                  <Icon xlinkHref={item.icon.xlinkHref} variant={item.icon.variant || ''} />
                )}
              </Box>
            ) : null}
            <Text mr="4px" color={isActive ? 'text_caption' : 'text_paragraph'} position="relative" fontSize="15px" fontWeight="500">
              {item.title}
            </Text>
          </HStack>

          <Icon
            svgH="12px"
            svgW="12px"
            boxH="12px"
            boxW="12px"
            xlinkHref="#icon-icon_arrow"
            variant="gray"
            svgFill="primary_gray"
            transition="transform 0.5s"
            transform={open ? 'rotate(180deg)' : 'rotate(0deg)'}
          />
        </Flex>
      </MenuItem>

      {open && (
        <>
          <Divider borderColor="border" />
          <Box
            overflow="hidden"
            display="flex"
            flexDirection="column"
            padding="16px 0px"
            gap="20px"
            border="none"
            boxShadow="none"
            borderRadius="0px 0px 8px 8px"
            bg="menu_item_bg"
            minW="unset"
          >
            {(item.children || []).map((child: NavMenuListItem) => {
              return <Item key={child.title} item={child} active={active} isChild />
            })}
          </Box>
        </>
      )}
    </Box>
  )
}

const Item = ({ item, active, isChild = false }: { item: NavMenuListItem; active: boolean; isChild?: boolean }) => {
  return item.type === '_blank' ? (
    <MenuItem
      as="a"
      href={item.path}
      target="_blank"
      {...(isChild ? { padding: '0px', bg: 'menu_item_bg' } : { bg: 'menu_item_bg', borderRadius: '8px', padding: '16px' })}
      sx={{
        p: {
          color: active ? 'text_caption' : 'text_paragraph'
        },
        svg: {
          fill: active ? 'text_caption' : 'text_paragraph'
        }
      }}
      _hover={{
        p: {
          color: 'text_caption'
        },
        svg: {
          fill: 'text_caption'
        }
      }}
    >
      {item.icon ? (
        <Box mr="12px">
          {typeof item.icon === 'string' ? (
            <Icon xlinkHref={item.icon} />
          ) : (
            <Icon xlinkHref={item.icon.xlinkHref} variant={item.icon.variant || ''} />
          )}
        </Box>
      ) : null}
      <Text>{item.title}</Text>
    </MenuItem>
  ) : (
    <MenuItem
      as={ReactRouterLink}
      to={item.path}
      {...(isChild
        ? {
            padding: '0px',
            bg: 'menu_item_bg'
          }
        : {
            bg: 'menu_item_bg',
            borderRadius: '8px',
            padding: '16px',
            minW: '220px'
          })}
      sx={{
        h: isChild ? '20px' : '52px',
        p: {
          color: active ? 'text_caption' : 'text_paragraph'
        },
        svg: {
          fill: active ? 'text_caption' : 'text_paragraph'
        }
      }}
      _hover={{
        p: {
          color: 'text_caption'
        },
        svg: {
          fill: 'text_caption'
        }
      }}
    >
      {item.icon ? (
        <Box mr="12px">
          {typeof item.icon === 'string' ? (
            <Icon xlinkHref={item.icon} />
          ) : (
            <Icon xlinkHref={item.icon.xlinkHref} variant={item.icon.variant || ''} />
          )}
        </Box>
      ) : null}
      <Text>{item.title}</Text>
    </MenuItem>
  )
}
